async (fn: () => Promise<unknown>) => {
    if (busyAction.current) return;
    busyAction.current = true;
    setWorking(true);
    setNotice("");
    try {
      await fn();
    } catch (err) {
      setNotice(err instanceof Error ? err.message : String(err));
    } finally {
      busyAction.current = false;
      setWorking(false);
    }
  }

