(decisionId: string, optionId: string) => {
    const dec = decisions.find((d) => d.id === decisionId);
    if (!dec) return;
    const opt = dec.options.find((o) => o.id === optionId);
    if (!opt) return;

    setDecisions((prev) =>
      prev.map((d) =>
        d.id === decisionId
          ? {
              ...d,
              selectedOptionId: optionId,
              enactedAt: new Date().toISOString(),
              enactedBy: 'Special Agent [Authorizing Officer]',
