      const replyMsg: RadioTransmission = {
        id: getTransmissionId(),
        channelId: selectedChannelId,
        callsign: activeChannel.callsign,
        unit: activeChannel.name,
        timestamp: new Date().toISOString().substring(11, 16) + ' UTC',
