useMemo(() => {
    return evidence.filter((e) => {
      // Storage zone filter
      if (activeZone !== 'all') {
        const itemZone = getZone(e.data.location);
        if (itemZone !== activeZone) return false;
      }

      // Material filter
      if (materialFilter !== 'All' && e.data.type !== materialFilter) {
        return false;
      }

      // Seal filter
      if (sealFilter !== 'All' && e.data.seal !== sealFilter) {
        return false;
      }

      // Search query
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        const str = [
          e.id,
          e.caseId || '',
          e.data.title || '',
          e.data.type || '',
          e.data.location || '',
          e.data.custodian || '',
          e.data.description || '',
          ...(e.data.tags || []),
        ]
          .join(' ')
          .toLowerCase();
        if (!str.includes(q)) return false;
      }

      return true;
    });
  }, [evidence, activeZone, materialFilter, sealFilter, searchQuery])

