      {
        id: 'eng-practical-bench',
        label: 'Practical Bench Repairs & Protocol Synthesis',
        pathwayType: 'practical',
        description: 'Advance through hands-on relay repairs, kernel thread isolation, and SpellForge compiler synthesis.',
