      return {
        worknetSim: advanceWorknetSimulation(state.worknetSim, tick, workplace),
        gameplay: { ...state.gameplay, player: { ...state.gameplay.player, worknetWorkplace: restoreWorkplace(workplace, tick, state.gameplay.player) } },
