          credits: s.gameplay.player.credits + caseDef.rewardCredits,
          bits: (s.gameplay.player.bits || 0) + caseDef.rewardBits,
          xp: newXP,
          level: newLevel,
        },
      },
    }));

    get().addSkillXP('Research', 35);
    get().recordWorldEvent({
      category: 'forensic',
      title: `Validated Case Resolution: ${caseDef.title}`,
